class Solution:
    def countShiftFamilies(self, words: List[str]) -> int:
        def shifted_equal(r, w, k):
            return all((ord(a) - 97 + k) % 26 == ord(b) - 97 for a, b in zip(r, w))
        reps = []
        for w in words:
            if not any(len(r) == len(w) and any(shifted_equal(r, w, k) for k in range(26))
                       for r in reps):
                reps.append(w)
        return len(reps)

