class Solution {
    public int countShiftFamilies(String[] words) {
        List<String> reps = new ArrayList<>();
        for (String w : words) {
            boolean found = false;
            for (String r : reps) {
                if (r.length() != w.length()) continue;
                for (int k = 0; k < 26 && !found; k++) found = shiftedEqual(r, w, k);
                if (found) break;
            }
            if (!found) reps.add(w);
        }
        return reps.size();
    }

    private boolean shiftedEqual(String r, String w, int k) {
        for (int i = 0; i < r.length(); i++)
            if ((r.charAt(i) - 'a' + k) % 26 != w.charAt(i) - 'a') return false;
        return true;
    }
}

