int countShiftFamilies(char** words, int wordsSize) {
    char** reps = malloc(wordsSize * sizeof(char*));
    int f = 0;
    for (int i = 0; i < wordsSize; i++) {
        bool found = false;
        for (int j = 0; j < f && !found; j++) {
            if (strlen(reps[j]) != strlen(words[i])) continue;
            for (int k = 0; k < 26 && !found; k++) found = shiftedEqual(reps[j], words[i], k);
        }
        if (!found) reps[f++] = words[i];
    }
    free(reps);
    return f;
}

