class Solution:
    def countShiftFamilies(self, words: List[str]) -> int:
        def normal(w):
            return "".join(chr((ord(c) - ord(w[0])) % 26 + 97) for c in w)
        keys = sorted(normal(w) for w in words)
        return sum(1 for i in range(len(keys)) if i == 0 or keys[i] != keys[i - 1])

