class Solution {
    public int countShiftFamilies(String[] words) {
        String[] keys = new String[words.length];
        for (int i = 0; i < words.length; i++) keys[i] = normal(words[i]);
        Arrays.sort(keys);
        int families = 0;
        for (int i = 0; i < keys.length; i++) if (i == 0 || !keys[i].equals(keys[i - 1])) families++;
        return families;
    }

    private String normal(String w) {
        char[] out = new char[w.length()];
        for (int i = 0; i < out.length; i++) out[i] = (char) ((w.charAt(i) - w.charAt(0) + 26) % 26 + 'a');
        return new String(out);
    }
}

