    return strcmp(*(char* const*) a, *(char* const*) b);
}

int countShiftFamilies(char** words, int wordsSize) {
    char** keys = malloc(wordsSize * sizeof(char*));
    for (int i = 0; i < wordsSize; i++) {
        size_t len = strlen(words[i]);
        keys[i] = malloc(len + 1);
        for (size_t j = 0; j < len; j++) keys[i][j] = (words[i][j] - words[i][0] + 26) % 26 + 'a';
        keys[i][len] = '\0';
    }
    qsort(keys, wordsSize, sizeof(char*), cmpStr);
    int families = 0;
    for (int i = 0; i < wordsSize; i++) if (i == 0 || strcmp(keys[i], keys[i - 1]) != 0) families++;
    for (int i = 0; i < wordsSize; i++) free(keys[i]);
    free(keys);
    return families;
}

