static unsigned long long fnv(const char* s) {
    unsigned long long h = 1469598103934665603ULL;
    for (; *s; s++) h = (h ^ (unsigned char) *s) * 1099511628211ULL;
    return h;
}

int countShiftFamilies(char** words, int wordsSize) {
    unsigned cap = 1;
    while (cap < 2u * wordsSize) cap <<= 1;
    char** table = calloc(cap, sizeof(char*));
    int families = 0;
    for (int i = 0; i < wordsSize; i++) {
        size_t len = strlen(words[i]);
        char* key = malloc(len + 1);
        for (size_t j = 0; j < len; j++) key[j] = (words[i][j] - words[i][0] + 26) % 26 + 'a';
        key[len] = '\0';
        unsigned s = (unsigned) (fnv(key) >> 32) & (cap - 1);
        while (table[s] && strcmp(table[s], key) != 0) s = (s + 1) & (cap - 1);
        if (table[s]) free(key);
        else { table[s] = key; families++; }
    }
    for (unsigned s = 0; s < cap; s++) free(table[s]);
    free(table);
    return families;
}
